def commonIntervals(k, intervals):
    events = []
    for _, s, e in intervals:
        events.append((s, 0))
        events.append((e, 1))
    events.sort()
    count = 0
    begin = 0
    res = []
    for x, kind in events:
        if kind == 0:
            count += 1
            if count == k:
                begin = x
        else:
            if count == k:
                res.append([begin, x])
            count -= 1
    return res
